#pragma once
#include <cstdint>
#include <string_view>

#include "hud_font_data.hpp"

// The overlay's built-in font: Titillium Web SemiBold (SIL OFL 1.1) as a signed distance field atlas,
// generated by native/tools/hud_font_sdf.py. Metrics are in em units; a text box is one em tall with
// the caps and descenders centred in it.

namespace hud::font {

constexpr const Glyph *find(uint32_t cp)
{
    uint32_t lo = 0, hi = GLYPH_COUNT;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (GLYPHS[mid].cp < cp)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo < GLYPH_COUNT && GLYPHS[lo].cp == cp ? &GLYPHS[lo] : nullptr;
}

constexpr const Glyph *glyph(uint32_t cp)
{
    if (cp == '\t' || cp == 0xa0)
        cp = ' ';
    if (auto g = find(cp))
        return g;
    return find('?');
}

constexpr float kern(uint32_t left, uint32_t right)
{
    if (!KERN_COUNT || left > 0xffff || right > 0xffff)
        return 0;
    uint32_t pair = left << 16 | right, lo = 0, hi = KERN_COUNT;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (KERNS[mid].pair < pair)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo < KERN_COUNT && KERNS[lo].pair == pair ? KERNS[lo].adjust : 0;
}

constexpr float descent()
{
    float d = 0;
    for (uint32_t cp : {'g', 'j', 'p', 'q', 'y'})
        if (auto g = find(cp))
            d = d > g->y1 ? d : g->y1;
    return d - SPREAD / ATLAS_EM;
}

constexpr float BASELINE = (1.0f - CAP_HEIGHT - descent()) / 2 + CAP_HEIGHT;

constexpr uint32_t decode(std::string_view s, size_t &i)
{
    unsigned char b = static_cast<unsigned char>(s[i++]);
    if (b < 0x80)
        return b;
    int more = b >= 0xf0 ? 3 : b >= 0xe0 ? 2 : b >= 0xc0 ? 1 : -1;
    if (more < 0)
        return 0xfffd;
    uint32_t cp = b & (0x3f >> more);
    for (; more; more--) {
        if (i >= s.size() || (static_cast<unsigned char>(s[i]) & 0xc0) != 0x80)
            return 0xfffd;
        cp = cp << 6 | (static_cast<unsigned char>(s[i++]) & 0x3f);
    }
    return cp;
}

}
